def transform(grid):
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    best_H = 1
    best_n = 0
    best_map = {}
    best_score = -1.0

    # Try to find the smallest period H and noise value n
    # H is the horizontal period, valid pattern is consistent along diagonals (c - r)
    for H in range(1, cols + 1):
        # Try each value 0-9 as the noise value
        for n in range(10):
            consistent = True
            map = {}

            # Check consistency for given H and n
            for r in range(rows):
                for c in range(cols):
                    val = grid[r][c]
                    if val == n:
                        continue # Skip noise value

                    key = (c - r) % H
                    if key in map:
                        if map[key] != val:
                            consistent = False
                            break
                    else:
                        map[key] = val
                if not consistent:
                    break

            if not consistent:
                continue

            # Score based on coverage relative to H
            # Higher score means more keys are filled consistently
            score = len(map) / H

            if score > best_score + 1e-9:
                best_score = score
                best_H = H
                best_n = n
                best_map = map
            elif abs(score - best_score) < 1e-9:
                # Tie-breaker: prefer smaller period
                if H < best_H:
                    best_H = H
                    best_n = n
                    best_map = map

    # Reconstruct the grid
    res = [[0] * cols for _ in range(rows)]

    if best_map:
        for r in range(rows):
            for c in range(cols):
                key = (c - r) % best_H
                val = best_map.get(key)
                if val is not None:
                    res[r][c] = val

    return res
